{"query":"

  fragment SubscriptionOffer on SubscriptionResponse {
    price {
      amount
      currency
    }
    offerId
    renewalPrice {
      amount
      currency
    }
    monthlyPrice {
      amount
      currency
    }
    duration {
      amount
      timeUnit
    }
    renewalDuration {
      amount
      timeUnit
    }
    subscriptionPeriod
    type
    totalCommitment {
      amount
      currency
    }
  }


  fragment CatalogueOffer on MembershipOffer {
    membershipOfferId
    plan {
      planName
      membershipTier {
        membershipTierId
        policies {
          autoRenewalPolicy {
            deactivationConditions
          }
          durationPolicy {
            amount
            timeUnit
          }
        }
        valueProposition {
          ... on LimitedMembershipPerk {
            __typename
            type
            usageQuota
          }
          ... on UnlimitedMembershipPerk {
            __typename
            type
          }
        }
        loyaltyRewardsProgram {
          loyaltyRewards
        }
      }
    }
  }

  query SubscriptionOffers($request: SubscriptionOffersRequest)  {
    subscriptionOffers(request: $request) {
      ...SubscriptionOffer
      catalogueOffer {
        ...CatalogueOffer
      }
    }
  }
","variables":{"request":{}},"operationName":"SubscriptionOffers"}

